(1414,2974,'Tuberculosis of the lungs.','en',2,'2026-05-31 02:13:37',NULL,NULL,'3676FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1415,2975,'Purplish or brownish red discoloration, easily visible through the epidermis, caused by hemorrhage into the tissues.','en',2,'2026-05-31 02:13:37',NULL,NULL,'3669FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1416,2977,'A cutaneous inflammatory reaction occurring as a result of exposure to ionizing radiation.','en',2,'2026-05-31 02:13:37',NULL,NULL,'3661FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
