('validation.disable','false','Disables validation of OpenMRS Objects. Only takes affect on next restart. Warning: only do this is you know what you are doing!','346a9dc0-5f6a-462d-9065-85bcc7b62203',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.allowOverlappingVisits','false',NULL,'e0376867-c667-4c81-b82f-f65ec7bfd5c7','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.assignmentHandler','org.openmrs.api.handler.ExistingVisitAssignmentHandler',NULL,'c90dd1db-0611-451a-94c4-ac4b0f44035d',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.autoCloseVisitType',NULL,'comma-separated list of the visit type(s) to automatically close','7abb62f4-81a6-4145-ac0d-f01034d666ce',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.enabled','true','Set to true to enable the Visits feature. This will replace the \'Encounters\' tab with a \'Visits\' tab on the dashboard.','9c594c46-482d-48b3-9643-05641111fc9f','org.openmrs.customdatatype.datatype.BooleanDatatype',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('visits.encounterTypeToVisitTypeMapping',NULL,'Specifies how encounter types are mapped to visit types when automatically assigning encounters to visits. e.g 1:1, 2:1, 3:2 in the format encounterTypeId:visitTypeId or encounterTypeUuid:visitTypeUuid or a combination of encounter/visit type uuids and ids e.g 1:759799ab-c9a5-435e-b671-77773ada74e4','c84f289c-3869-4683-9b14-ebc47c374212',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.allowedips',NULL,'A comma-separate list of IP addresses that are allowed to access the web services. An empty string allows everyone to access all ws. \n        IPs can be declared with bit masks e.g. 10.0.0.0/30 matches 10.0.0.0 - 10.0.0.3 and 10.0.0.0/24 matches 10.0.0.0 - 10.0.0.255.','53c079f0-d633-4f77-9dca-bedbd642f63c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.enableStackTraceDetails','true','If the value of this setting is \"true\", then the details of the stackTrace would be shown in the error response. However, the recommendation is to keep it as \"false\", from the Security perspective, to avoid leaking implementation details.','92c226a2-4d41-49ed-ab00-60f2e8e1c134',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.mandatory','false','true/false whether or not the webservices.rest module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','6714dcdd-b34b-46ae-9cd0-6be9cf398203',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.maxResultsAbsolute','100','The absolute max results limit. If the client requests a larger number of results, then will get an error','d30013af-e4e2-4e29-b540-50c6343266b6',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.maxResultsDefault','50','The default max results limit if the user does not provide a maximum when making the web service call.','510a2bc2-82c2-4ceb-94f8-846f1336326d',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.quietDocs','true','If the value of this setting is \"true\", then nothing is logged while the Swagger specification is being generated.','5497bf0c-2947-451f-80e1-f08df00bddee',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.started','true','DO NOT MODIFY. true/false whether or not the webservices.rest module has been started.  This is used to make sure modules that were running  prior to a restart are started again','75cedd1e-edad-40aa-84e4-f942d803d858',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('webservices.rest.uriPrefix',NULL,'The URI prefix through which clients consuming web services will connect to the web application, should be of the form http://{ipAddress}:{port}/{contextPath}','f99159fe-a657-46ef-bd52-a23efd53d7e7',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
